#nullable enable // autogenerated

using System.Linq;
using MVZ2.GameContent.Buffs.Entities;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Seeds;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Stages
{
    [AutoStageDefinition(VanillaStageNames.HeavyWeaponVSMannequin)]
    public class HeavyWeaponVSMannequin : HeavyWeaponStageBase
    {
        public HeavyWeaponVSMannequin(string nsp, string name) : base(nsp, name)
        {
            var waveStageBehaviour = new WaveStageBehaviour(this)
            {
                SpawnFlagZombie = false
            };
        }
        protected override NamespaceID[] GetBlueprintsID()
        {
            return new NamespaceID[]
            {
                VanillaBlueprintID.heavyWeaponFlashbang,
                VanillaBlueprintID.HeavyWeaponGrenade,
                VanillaBlueprintID.HeavyWeaponMolotov,
                VanillaBlueprintID.HeavyWeaponSwitchProjectile,
                VanillaBlueprintID.HeavyWeaponRegen,
                VanillaBlueprintID.heavyWeaponSpread,
                VanillaBlueprintID.HeavyWeaponBulletUpgrade,
                VanillaBlueprintID.HeavyWeaponExtraLife,
                VanillaContraptionID.devourer,
                VanillaContraptionID.devourer,
            };
        }
        public override void OnSetup(LevelEngine level)
        {
            base.OnSetup(level);

            var allContraptions = new NamespaceID[]
            {
        VanillaContraptionID.furnace,
        VanillaContraptionID.stoneShield,
            };

            int Num = 2;

            var rand = new System.Random();

            // 随机选 Num 个不重复装置
            var selectedContraptions = allContraptions.OrderBy(x => rand.Next()).Take(Num).ToArray();

            var usedPositions = new System.Collections.Generic.HashSet<(int, int)>();

            for (int i = 0; i < Num; i++)
            {
                int col, row;
                do
                {
                    col = rand.Next(0, 8);  // 0~7列
                    row = rand.Next(0, 5);  // 0~4行
                } while (!usedPositions.Add((col, row)));

                float x = level.GetEntityColumnX(col);
                float z = level.GetEntityLaneZ(row);
                float y = level.GetGroundY(x, z);
                Vector3 pos = new Vector3(x, y, z);

                var contraption = level.Spawn(selectedContraptions[i], pos, null);
                var buff = contraption?.AddBuff<CharmBuff>();
                if (buff != null)
                    CharmBuff.SetPermanent(buff, level.Option.RightFaction);  // 让 charm 的 Set 修饰器指向敌方
            }
        }
    }
}
